    @Test
    public void testDecompressConcatenatedFlag() throws Exception {
        // Test the constructor with decompressUntilEOF
        CompressorStreamFactory factoryWithEOF = new CompressorStreamFactory(true);
        byte[] data = new byte[12];
        data[0] = 'B'; data[1] = 'Z'; data[2] = 'h';
        InputStream in = new ByteArrayInputStream(data);
        CompressorInputStream result = factoryWithEOF.createCompressorInputStream(in);
        assertNotNull(result);
